package com.rpb.reservation.workforce;
import com.rpb.reservation.workforce.documents.*;import com.rpb.reservation.workforce.documents.expiry.*;import com.rpb.reservation.workforce.application.*;import static com.rpb.reservation.workforce.application.WorkforceDtos.*;
import com.rpb.reservation.workforce.domain.WorkforceException;import com.rpb.reservation.walkin.api.CurrentActor;import java.time.*;import java.util.*;import org.junit.jupiter.api.*;
import static org.assertj.core.api.Assertions.*;import static org.mockito.Mockito.*;import static org.mockito.ArgumentMatchers.*;
class WorkforceDocumentExpiryPostgresTest extends WorkforcePostgresTest {
 EmployeeDocumentService docs;DocumentExpiryService expiry;UUID employee,type;LocalDate today=LocalDate.of(2026,10,29);
 @BeforeEach void expirySetup(TestInfo info){if(info.getTestMethod().orElseThrow().getDeclaringClass()!=WorkforceDocumentExpiryPostgresTest.class)return;var mapper=new com.fasterxml.jackson.databind.ObjectMapper().findAndRegisterModules();docs=proxy(new EmployeeDocumentService(access,repository,new DocumentRepository(jdbc),new WorkforceAudit(logs,mapper)));expiry=proxy(new DocumentExpiryService(access,new DocumentExpiryRepository(jdbc),Clock.fixed(Instant.parse("2026-10-28T18:00:00Z"),ZoneOffset.UTC)));employee=UUID.randomUUID();employees.save(admin,store,employee,command(0,List.of(store),company,null,null));type=docs.types(admin,store).getFirst().id();}
 UUID document(UUID employee,LocalDate date){var id=UUID.randomUUID();docs.save(admin,store,employee,id,new DocumentDtos.Write(0L,type,"PRIVATE-NUMBER",date,"PRIVATE-NOTES",false));return id;}
 @Test void boundariesNullDeletedAndDisabledTypeUseStoreDateWithoutChangingData(){var expired=document(employee,today.minusDays(1));var due=document(employee,today);document(employee,today.plusDays(30));document(employee,today.plusDays(31));document(employee,null);var deleted=document(employee,today.plusDays(1));docs.save(admin,store,employee,deleted,new DocumentDtos.Write(1L,type,"PRIVATE-NUMBER",today.plusDays(1),"PRIVATE-NOTES",true));var typeRow=docs.types(admin,store).getFirst();docs.type(admin,store,type,new DocumentDtos.TypeWrite(1L,typeRow.name(),false,false));var before=jdbc.queryForList("select to_jsonb(d)::text from workforce_employee_documents d where tenant_id=? order by id",String.class,tenant);var page=expiry.list(admin,store,30,"all",50,0);assertThat(page.today()).isEqualTo(today);assertThat(page.due()).isEqualTo(2);assertThat(page.expired()).isEqualTo(1);assertThat(page.items()).extracting(DocumentExpiryDtos.Item::documentId).contains(expired,due).doesNotContain(deleted);assertThat(page.items().stream().filter(r->r.documentId().equals(due)).findFirst().orElseThrow().daysRemaining()).isZero();assertThat(expiry.list(admin,store,30,"expired",50,0).total()).isEqualTo(1);assertThat(expiry.list(admin,store,7,"due",50,0).total()).isEqualTo(1);assertThat(jdbc.queryForList("select to_jsonb(d)::text from workforce_employee_documents d where tenant_id=? order by id",String.class,tenant)).isEqualTo(before);}
 @Test void managerCannotSeePartiallyManagedEmployeesOrOtherStoresAndStaffIsDenied(){document(employee,today);jdbc.update("insert into workforce_work_stores(employee_id,tenant_id,store_id,started_on) values(?,?,?,'2026-10-01')",employee,tenant,sibling);var managerId=account("store_manager",Set.of(store),Set.of("workforce.view"));jdbc.update("insert into workforce_administrators(tenant_id,store_id,account_id,employee_manage,version) values(?,?,?,true,1)",tenant,store,managerId);var manager=new CurrentActor(tenant,managerId,"staff",Set.of("store_manager"),Set.of("workforce.view"),Set.of(store));assertThat(expiry.list(manager,store,30,"all",50,0).total()).isZero();assertThat(expiry.list(admin,store,30,"all",50,0).total()).isEqualTo(1);assertThat(expiry.list(admin,sibling,30,"all",50,0).total()).isEqualTo(1);assertThatThrownBy(()->expiry.list(manager,sibling,30,"all",50,0)).isInstanceOf(WorkforceException.class).extracting("status").isEqualTo(403);var staff=new CurrentActor(tenant,managerId,"staff",Set.of("store_staff"),Set.of("workforce.view"),Set.of(store));jdbc.update("delete from workforce_administrators where tenant_id=? and account_id=?",tenant,managerId);assertThatThrownBy(()->expiry.list(staff,store,30,"all",50,0)).isInstanceOf(WorkforceException.class).extracting("status").isEqualTo(403);}
 @Test void paginationCountsAllRowsAndTimezoneBoundaryIsNotHostDependent(){for(int n=0;n<61;n++)document(employee,today);var first=expiry.list(admin,store,30,"due",50,0);var second=expiry.list(admin,store,30,"due",50,50);assertThat(first.total()).isEqualTo(61);assertThat(first.items()).hasSize(50);assertThat(second.items()).hasSize(11);assertThat(first.items()).doesNotContainAnyElementsOf(second.items());jdbc.update("update stores set timezone='America/Los_Angeles' where tenant_id=? and id=?",tenant,store);assertThat(expiry.list(admin,store,30,"due",50,0).today()).isEqualTo(today.minusDays(1));}
 @Test void parametersTenantAndAppGateCannotBypassScope(){for(int days:List.of(0,366))assertThatThrownBy(()->expiry.list(admin,store,days,"all",50,0)).isInstanceOf(WorkforceException.class).extracting("status").isEqualTo(400);assertThatThrownBy(()->expiry.list(admin,store,30,"anything",50,0)).isInstanceOf(WorkforceException.class);var foreign=new CurrentActor(UUID.randomUUID(),adminId,"staff",admin.roles(),admin.permissions(),admin.storeIds());assertThatThrownBy(()->expiry.list(foreign,store,30,"all",50,0)).isInstanceOf(WorkforceException.class).extracting("status").isEqualTo(404);for(var reason:List.of(com.rpb.reservation.appgate.domain.AppGateDenyReason.APP_DISABLED,com.rpb.reservation.appgate.domain.AppGateDenyReason.TENANT_APP_NOT_ENABLED,com.rpb.reservation.appgate.domain.AppGateDenyReason.STORE_APP_NOT_ENABLED)){doReturn(com.rpb.reservation.appgate.domain.AppGateDecision.deny("workforce",tenant,store,"workforce.view",reason)).when(gate).evaluate(any());assertThatThrownBy(()->expiry.list(admin,store,30,"all",50,0)).isInstanceOf(WorkforceException.class).extracting("status").isEqualTo(403);}}
 @Test void employeeBatchesAndSingleEmployeeFilterUseTheSameScopeAndDateRules(){document(employee,today.minusDays(1));document(employee,today);document(employee,today.plusDays(30));document(employee,today.plusDays(31));document(employee,null);var e=repository.find(tenant,employee).orElseThrow();var second=UUID.randomUUID();employees.save(admin,store,second,new EmployeeWrite(0L,"E002","Second","","","Service",e.hireDate(),null,"active",company,e.companyEffectiveDate(),store,List.of(store),null,"",""));document(second,today.plusDays(10));var counts=expiry.employeeCounts(admin,store,30,List.of(employee,second,UUID.randomUUID(),employee));assertThat(counts.items()).hasSize(2);var first=counts.items().stream().filter(c->c.employeeId().equals(employee)).findFirst().orElseThrow();assertThat(first.due()).isEqualTo(2);assertThat(first.expired()).isEqualTo(1);assertThat(expiry.list(admin,store,30,"all",50,0,second).items()).allMatch(row->row.employeeId().equals(second)).hasSize(1);assertThat(expiry.list(admin,store,30,"all",50,0,UUID.randomUUID()).total()).isZero();assertThat(expiry.employeeCounts(admin,sibling,30,List.of(employee,second)).items()).isEmpty();}
 @Test void employeeBatchIdsCannotExposePartiallyManagedOrForeignEmployees(){document(employee,today);jdbc.update("insert into workforce_work_stores(employee_id,tenant_id,store_id,started_on) values(?,?,?,'2026-10-01')",employee,tenant,sibling);var managerId=account("store_manager",Set.of(store),Set.of("workforce.view"));jdbc.update("insert into workforce_administrators(tenant_id,store_id,account_id,employee_manage,version) values(?,?,?,true,1)",tenant,store,managerId);var manager=new CurrentActor(tenant,managerId,"staff",Set.of("store_manager"),Set.of("workforce.view"),Set.of(store));assertThat(expiry.employeeCounts(manager,store,30,List.of(employee)).items()).isEmpty();assertThat(expiry.list(manager,store,30,"all",50,0,employee).items()).isEmpty();assertThatThrownBy(()->expiry.employeeCounts(manager,sibling,30,List.of(employee))).isInstanceOf(WorkforceException.class).extracting("status").isEqualTo(403);var foreign=new CurrentActor(UUID.randomUUID(),adminId,"staff",admin.roles(),admin.permissions(),admin.storeIds());assertThatThrownBy(()->expiry.employeeCounts(foreign,store,30,List.of(employee))).isInstanceOf(WorkforceException.class).extracting("status").isEqualTo(404);}
 @Test void employeeBatchInputIsBoundedAndGateProtected(){assertThatThrownBy(()->expiry.employeeCounts(admin,store,30,List.of())).isInstanceOf(WorkforceException.class).extracting("status").isEqualTo(400);assertThatThrownBy(()->expiry.employeeCounts(admin,store,30,Collections.nCopies(101,employee))).isInstanceOf(WorkforceException.class).extracting("status").isEqualTo(400);assertThatThrownBy(()->expiry.employeeCounts(admin,store,0,List.of(employee))).isInstanceOf(WorkforceException.class);for(var reason:List.of(com.rpb.reservation.appgate.domain.AppGateDenyReason.APP_DISABLED,com.rpb.reservation.appgate.domain.AppGateDenyReason.TENANT_APP_NOT_ENABLED,com.rpb.reservation.appgate.domain.AppGateDenyReason.STORE_APP_NOT_ENABLED)){doReturn(com.rpb.reservation.appgate.domain.AppGateDecision.deny("workforce",tenant,store,"workforce.view",reason)).when(gate).evaluate(any());assertThatThrownBy(()->expiry.employeeCounts(admin,store,30,List.of(employee))).isInstanceOf(WorkforceException.class).extracting("status").isEqualTo(403);}}
}
